  pages.push({path:"/beach-pilates-nassau/",content:"<section class=\"page-hero\"><img src=\"https://static.wixstatic.com/media/8baa80_e6da1e7829a24bf1ac5cd51a1bd1ceae~mv2.jpg\" alt=\"Real Tranquilitas white beachside cabanas and massage stations set up on a sandy shoreline\" fetchpriority=\"high\" decoding=\"async\"><div class=\"container\"><div class=\"breadcrumbs\"><a href=\"/\">Tranquilitas Bahamas</a> / Beach Pilates</div><p class=\"eyebrow light\">01 / MINDFUL MOVEMENT</p><h1>Movement, with the sea beside you.</h1><p class=\"lead\">Explore a private mat Pilates session in a suitable Nassau or Paradise Island beach setting. Instructor, venue access and your custom quote are confirmed after your enquiry.</p><div class=\"actions\"><a class=\"btn btn-aqua\" href=\"/book/?service=Beach%20Pilates\">Request this experience</a><a class=\"btn btn-ghost\" href=\"/experiences/\">View all experiences</a></div></div></section><section class=\"section\"><div class=\"container content-layout\"><article class=\"prose\"><p style=\"font-family:var(--display);font-size:1.55rem;line-height:1.55\">Explore a private mat Pilates session in a suitable Nassau or Paradise Island beach setting. Instructor, venue access and your custom quote are confirmed after your enquiry.</p><figure class=\"wellness-proof\"><img src=\"https://static.wixstatic.com/media/8baa80_6fb9123c62334a47aa7ffb20016b26aa~mv2.png\" alt=\"Tranquilitas therapist delivering a real beachside massage on a Nassau shoreline\" loading=\"lazy\" decoding=\"async\"><figcaption>Actual Tranquilitas beach massage photo used to show the setting, not a past Pilates class.</figcaption></figure><h2>A new way to enjoy the coast</h2><p>Whether you&#39;re traveling alone, with a partner or a group, tell us your experience level, preferred time and what you want from a mat session.</p><h2>Instructor and access first</h2><p>A qualified Pilates instructor, suitable shaded space, weather, beach rules and property permission all need to be verified before we accept a booking.</p><h2>Pair it with massage</h2><p>If you want a wider wellness morning, we can assess pairing movement with an existing Tranquilitas massage service, subject to separate staffing and pricing.</p><div class=\"inline-info\"><strong>IMPORTANT BOOKING INFORMATION</strong><p>Pilates is a request-based concept. We are not claiming a scheduled class or guaranteed instructor.</p></div></article><aside class=\"sidebar\"><p class=\"eyebrow\">PERSONAL QUOTATION</p><h3>Tell us the plan.</h3><p>Share your location, date, desired experience and number of guests. Our Nassau team will confirm feasibility and pricing.</p><a href=\"/book/?service=Beach%20Pilates\" class=\"btn btn-night\">Request a proposal</a><a class=\"btn btn-outline\" href=\"https://wa.me/12428168286?text=Hello%20Tranquilitas%2C%20I%20would%20like%20to%20enquire%20about%20Beach%20Pilates.\" target=\"_blank\" rel=\"noopener noreferrer\">WhatsApp our team</a><hr><p class=\"smallnote\">This is an enquiry, not an instant booking. Final staffing, service and payment details require confirmation.</p></aside></div></section><section class=\"section muted\"><div class=\"container\"><div class=\"heading\"><div><p class=\"eyebrow\">DISCOVER MORE</p><h2>Another way<br><em>to unwind.</em></h2></div></div><div class=\"wellness-related\"><a href=\"/villa-wellness-packages-bahamas/\">Villa Wellness Packages ↗</a><a href=\"/bespoke-wellness-bahamas/\">Special &amp; Bespoke Requests ↗</a></div></div></section>",opts:{image:"https://static.wixstatic.com/media/8baa80_e6da1e7829a24bf1ac5cd51a1bd1ceae~mv2.jpg"}});
  pages.push({path:"/villa-wellness-packages-bahamas/",content:"<section class=\"page-hero\"><img src=\"https://static.wixstatic.com/media/8baa80_43023c407ba041e4aa27791a2c22479f~mv2.jpg\" alt=\"Tranquilitas massage therapist giving a real outdoor massage on an ocean-view private villa terrace\" fetchpriority=\"high\" decoding=\"async\"><div class=\"container\"><div class=\"breadcrumbs\"><a href=\"/\">Tranquilitas Bahamas</a> / Villa Wellness Packages</div><p class=\"eyebrow light\">02 / VILLA RETREATS</p><h1>Your villa. Your private wellness retreat.</h1><p class=\"lead\">Bring a carefully planned massage and wellness experience to your villa in Nassau or Paradise Island. We&#39;ll work with your guest count, setting and desired schedule.</p><div class=\"actions\"><a class=\"btn btn-aqua\" href=\"/book/?service=Villa%20Wellness%20Package\">Request this experience</a><a class=\"btn btn-ghost\" href=\"/experiences/\">View all experiences</a></div></div></section><section class=\"section\"><div class=\"container content-layout\"><article class=\"prose\"><p style=\"font-family:var(--display);font-size:1.55rem;line-height:1.55\">Bring a carefully planned massage and wellness experience to your villa in Nassau or Paradise Island. We&#39;ll work with your guest count, setting and desired schedule.</p><figure class=\"wellness-proof\"><img src=\"https://static.wixstatic.com/media/8baa80_c8c003a4e2964c5181ce9d40ca5d5161~mv2.jpg\" alt=\"Two Tranquilitas massage therapists working together during a treatment\" loading=\"lazy\" decoding=\"async\"><figcaption>Real Tranquilitas therapist photography; new villa package inclusions are agreed individually.</figcaption></figure><h2>Start with established care</h2><p>Mobile massage and couples treatments form a dependable foundation. Group sessions, therapist numbers and setup requirements are planned around availability.</p><h2>Make room for something extra</h2><p>You can ask about Pilates, stretching or other curated wellness elements. These are only included if the relevant professionals and equipment can be confirmed.</p><h2>Tailored timing and pricing</h2><p>Half-day or longer itineraries are possible concepts rather than fixed products. We quote the actual number of guests, venue, schedule and requested extras.</p><div class=\"inline-info\"><strong>IMPORTANT BOOKING INFORMATION</strong><p>There is no fixed villa package price. Staffing, access and every inclusion are confirmed before payment.</p></div></article><aside class=\"sidebar\"><p class=\"eyebrow\">PERSONAL QUOTATION</p><h3>Tell us the plan.</h3><p>Share your location, date, desired experience and number of guests. Our Nassau team will confirm feasibility and pricing.</p><a href=\"/book/?service=Villa%20Wellness%20Package\" class=\"btn btn-night\">Request a proposal</a><a class=\"btn btn-outline\" href=\"https://wa.me/12428168286?text=Hello%20Tranquilitas%2C%20I%20would%20like%20to%20enquire%20about%20Villa%20Wellness%20Package.\" target=\"_blank\" rel=\"noopener noreferrer\">WhatsApp our team</a><hr><p class=\"smallnote\">This is an enquiry, not an instant booking. Final staffing, service and payment details require confirmation.</p></aside></div></section><section class=\"section muted\"><div class=\"container\"><div class=\"heading\"><div><p class=\"eyebrow\">DISCOVER MORE</p><h2>Another way<br><em>to unwind.</em></h2></div></div><div class=\"wellness-related\"><a href=\"/beach-pilates-nassau/\">Beach Pilates ↗</a><a href=\"/bespoke-wellness-bahamas/\">Special &amp; Bespoke Requests ↗</a></div></div></section>",opts:{image:"https://static.wixstatic.com/media/8baa80_43023c407ba041e4aa27791a2c22479f~mv2.jpg"}});
  pages.push({path:"/bespoke-wellness-bahamas/",content:"<section class=\"page-hero\"><img src=\"https://static.wixstatic.com/media/8baa80_caa346c70e3747a9895e8f0fae984d5f~mv2.jpg\" alt=\"Real Tranquilitas group beach massage setup with multiple shaded white treatment cabanas\" fetchpriority=\"high\" decoding=\"async\"><div class=\"container\"><div class=\"breadcrumbs\"><a href=\"/\">Tranquilitas Bahamas</a> / Special &amp; Bespoke Requests</div><p class=\"eyebrow light\">03 / YOUR OCCASION</p><h1>A wellness experience built around you.</h1><p class=\"lead\">For a celebration, private group, corporate occasion or unusual setting, tell us what you have in mind. We will build a practical proposal around what can actually be provided.</p><div class=\"actions\"><a class=\"btn btn-aqua\" href=\"/book/?service=Special%20%2F%20Bespoke%20Wellness%20Request\">Request this experience</a><a class=\"btn btn-ghost\" href=\"/experiences/\">View all experiences</a></div></div></section><section class=\"section\"><div class=\"container content-layout\"><article class=\"prose\"><p style=\"font-family:var(--display);font-size:1.55rem;line-height:1.55\">For a celebration, private group, corporate occasion or unusual setting, tell us what you have in mind. We will build a practical proposal around what can actually be provided.</p><figure class=\"wellness-proof\"><img src=\"https://static.wixstatic.com/media/8baa80_c8c003a4e2964c5181ce9d40ca5d5161~mv2.jpg\" alt=\"Two Tranquilitas therapists providing a real massage treatment\" loading=\"lazy\" decoding=\"async\"><figcaption>Real Tranquilitas photographs. Additional bespoke services are proposed and priced individually.</figcaption></figure><h2>Start with your brief</h2><p>Share the occasion, date, venue, group size and preferred treatments. We can explore couples, group massage, wellness breaks or tailored private setups.</p><h2>Practical details matter</h2><p>We verify therapist capacity, tables, access, shade, weather planning and any venue restrictions before promising delivery.</p><h2>A transparent proposal</h2><p>Your team will receive a quote that specifies actual inclusions, timing, equipment, partner services and booking terms.</p><div class=\"inline-info\"><strong>IMPORTANT BOOKING INFORMATION</strong><p>All bespoke requests require availability checks and a written quote. No unsupported package inclusions are guaranteed.</p></div></article><aside class=\"sidebar\"><p class=\"eyebrow\">PERSONAL QUOTATION</p><h3>Tell us the plan.</h3><p>Share your location, date, desired experience and number of guests. Our Nassau team will confirm feasibility and pricing.</p><a href=\"/book/?service=Special%20%2F%20Bespoke%20Wellness%20Request\" class=\"btn btn-night\">Request a proposal</a><a class=\"btn btn-outline\" href=\"https://wa.me/12428168286?text=Hello%20Tranquilitas%2C%20I%20would%20like%20to%20enquire%20about%20Special%20%2F%20Bespoke%20Wellness%20Request.\" target=\"_blank\" rel=\"noopener noreferrer\">WhatsApp our team</a><hr><p class=\"smallnote\">This is an enquiry, not an instant booking. Final staffing, service and payment details require confirmation.</p></aside></div></section><section class=\"section muted\"><div class=\"container\"><div class=\"heading\"><div><p class=\"eyebrow\">DISCOVER MORE</p><h2>Another way<br><em>to unwind.</em></h2></div></div><div class=\"wellness-related\"><a href=\"/beach-pilates-nassau/\">Beach Pilates ↗</a><a href=\"/villa-wellness-packages-bahamas/\">Villa Wellness Packages ↗</a></div></div></section>",opts:{image:"https://static.wixstatic.com/media/8baa80_caa346c70e3747a9895e8f0fae984d5f~mv2.jpg"}});
