  const sm=urls.filter(u=>u!=="/book/").map(path=>`<url><loc>${host+path}</loc><lastmod>${["/","/experiences/","/beach-pilates-nassau/","/villa-wellness-packages-bahamas/","/bespoke-wellness-bahamas/"].includes(path)?"2026-11-11":"2026-11-05"}</lastmod><changefreq>${path==="/"?"weekly":"monthly"}</changefreq><priority>${path==="/"?"1.0":path.startsWith("/journal/")?"0.6":"0.8"}</priority></url>`).join("");
